      "question": "","proposition": {"type":"condition","label":"Utilities air gallery serves RHOB process area; local indication P-R normally shows normal pressure band.","detail":"The Utilities air gallery distributes instrument air to the RHOB process area. The receiving header H-R at RHOB has a local indication point P-R that typically displays within a normal operating range (above 5.0 bar).","assessmentKind":"observation","sourceIds":["b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"],"claimIds":[]}},"n-gybvj2": {
